import ButtonClick from "./ButtonClick";

function App() {
  return (
    <div style={{ maxWidth: "400px", margin: "0 auto", textAlign: "center" }}>
      <h1>My Application</h1>

      {/* Reusing the component by passing different props */}
      <ButtonClick user="Alice" variant="primary" />
      <ButtonClick user="Bob" variant="secondary" />
    </div>
  );
}

export default App;
